interface Exports {
  rulesPerPlugin: Record<string, TSESLint.SharedConfig.RulesRecord>
  rules: TSESLint.SharedConfig.RulesRecord
  plugins: Record<string, TSESLint.FlatConfig.Plugin>
}

export const { rulesPerPlugin, rules, plugins }: Exports =
